-- 세트 522. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set522.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 522, 'SQL 중급 (3) 서브쿼리와 EXISTS: 스칼라·IN 서브쿼리, EXISTS, NOT IN 과 NULL 함정, 파생 테이블', 'JOIN 다음 단계입니다. 쿼리 안의 쿼리(서브쿼리)를 값 하나(스칼라), 목록(IN), 존재 여부(EXISTS), 임시 표(FROM 절)로 나눠 익히고, NOT IN 에 NULL 이 섞이면 결과가 통째로 비는 함정과 CASE 로 분류하는 법까지 터미널 실습으로 연습합니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 522);
UPDATE quest_set SET display_order = 743, unit_id = (SELECT id FROM unit WHERE id = 44), icon = '🧩' WHERE id = 522;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 1, '서브쿼리는 어디에 쓸까', '`WHERE amount > (SELECT AVG(amount) FROM orders)` 처럼 **괄호 안에 또 다른 SELECT** 를 넣은 것을 서브쿼리라고 합니다. 이 문장에서 괄호 안 `SELECT` 는 무엇을 돌려줄까요?', '`AVG` 는 여러 행을 합쳐 하나의 값으로 만듭니다.', NULL, NULL, '[]', 'choice', '["주문 전체 행 목록", "값 하나(평균), 바깥 쿼리가 이 값과 비교한다", "TRUE 또는 FALSE", "테이블 이름"]', 1, '`AVG` 는 값 하나를 돌려주므로 이 서브쿼리는 "값 하나"(스칼라 서브쿼리)입니다. 비교 연산자(`>`, `=`)에는 값 하나가 와야 합니다. 값이 여러 개 나오는 서브쿼리는 `IN` 과 함께 쓰고, 행이 있는지만 볼 때는 `EXISTS` 를 씁니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 2, '평균보다 큰 주문 찾기 (스칼라 서브쿼리)', '`mall` 데이터베이스에는 `members`(회원), `orders`(주문: `member_id` 가 회원 번호, `amount` 가 금액), `coupon_used`(쿠폰을 쓴 회원 번호) 테이블이 있습니다. 평균 금액을 직접 적지 말고 **서브쿼리로 계산**해서, **금액이 전체 주문 평균보다 큰 주문의 `id`** 를 `/tmp/big.txt` 에 저장하세요. (제목 줄 없이 `id` 만)', '`WHERE amount > (SELECT AVG(amount) FROM orders)` 모양입니다. `mariadb -N mall -e "..."` 의 출력을 `>` 로 저장합니다.', 'mariadb -N mall -e ''SELECT id FROM orders WHERE amount > (SELECT AVG(amount) FROM orders)'' > /tmp/big.txt
cat /tmp/big.txt

# 괄호 안 쿼리가 먼저 평균 하나를 만들고, 바깥 쿼리가 그 값과 비교한다 (2, 4, 6)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS mall; CREATE DATABASE mall; USE mall; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE orders (id INT PRIMARY KEY, member_id INT, amount INT); CREATE TABLE coupon_used (member_id INT); INSERT INTO members VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"),(4,\\"choi\\"),(5,\\"han\\"); INSERT INTO orders VALUES (1,1,30000),(2,1,70000),(3,2,15000),(4,3,50000),(5,3,20000),(6,3,90000); INSERT INTO coupon_used VALUES (1),(3),(NULL);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/big.txt)\\" = 3 ] ) && ( [ \\"$(sort /tmp/big.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"2 4 6 \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/big.txt)\\" = 3 ]"]}, {"label": "2·4·6 번 주문이다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/big.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"2 4 6 \\" ]"]}]', '[{"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB EXISTS", "url": "https://mariadb.com/kb/en/subqueries-and-exists/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 3, '주문한 적 있는 회원 (IN 서브쿼리)', '`mall` 데이터베이스(`mariadb -N mall -e ''쿼리''`)를 씁니다. `members`(id, name), `orders`(id, member_id, amount), `coupon_used`(member_id). 서브쿼리가 **값 여러 개(목록)** 를 돌려줄 때는 `IN` 으로 "이 목록 안에 있는가" 를 묻습니다. `orders` 에 `member_id` 로 **나온 적이 있는 회원**의 이름(`members.name`)을 `/tmp/buyers.txt` 에 저장하세요. (제목 줄 없이. 같은 회원이 두 번 나오면 안 됩니다)', '`WHERE id IN (SELECT member_id FROM orders)` 모양입니다. `IN` 은 목록에 중복이 있어도 회원을 한 번만 돌려줍니다.', 'mariadb -N mall -e ''SELECT name FROM members WHERE id IN (SELECT member_id FROM orders)'' > /tmp/buyers.txt
cat /tmp/buyers.txt

# 서브쿼리가 회원 번호 목록 (1,1,2,3,3,3) 을 만들고, IN 이 목록에 있는 회원만 남긴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS mall; CREATE DATABASE mall; USE mall; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE orders (id INT PRIMARY KEY, member_id INT, amount INT); CREATE TABLE coupon_used (member_id INT); INSERT INTO members VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"),(4,\\"choi\\"),(5,\\"han\\"); INSERT INTO orders VALUES (1,1,30000),(2,1,70000),(3,2,15000),(4,3,50000),(5,3,20000),(6,3,90000); INSERT INTO coupon_used VALUES (1),(3),(NULL);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/buyers.txt)\\" = 3 ] ) && ( [ \\"$(sort /tmp/buyers.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"kim lee park \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/buyers.txt)\\" = 3 ]"]}, {"label": "kim·lee·park 이다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/buyers.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"kim lee park \\" ]"]}]', '[{"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB EXISTS", "url": "https://mariadb.com/kb/en/subqueries-and-exists/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 4, 'IN 서브쿼리 조립', '주문한 적 있는 회원의 이름을 **이름순**으로 보는 쿼리입니다. 서브쿼리는 괄호 안에 들어갑니다. SQL 에서 쓰는 순서대로 놓으세요.', '서브쿼리는 바깥 WHERE 의 괄호 안에 들어갑니다. 바깥 쿼리를 한 문장으로 읽어 보세요.', NULL, NULL, '[]', 'order', '["WHERE id IN (", "SELECT name", ")", "FROM members", "SELECT member_id FROM orders", "ORDER BY name"]', NULL, '바깥 쿼리 `SELECT name FROM members WHERE id IN (` 다음에 서브쿼리 `SELECT member_id FROM orders` 가 오고 `)` 로 닫습니다. `ORDER BY` 는 바깥 쿼리의 맨 끝입니다.', '[1, 3, 0, 4, 2, 5]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 5, 'EXISTS 는 무엇을 확인할까', '`EXISTS (SELECT 1 FROM orders o WHERE o.member_id = m.id)` 는 바깥 쿼리의 회원 한 명마다 안쪽 쿼리를 실행합니다. `EXISTS` 가 결과로 보는 것은 무엇일까요?', '`IN` 은 값 목록을 보지만 `EXISTS` 는 다른 것을 봅니다.', NULL, NULL, '[]', 'choice', '["안쪽 쿼리가 돌려준 값의 합계", "안쪽 쿼리에 결과 행이 하나라도 있는가(참/거짓)", "안쪽 쿼리가 돌려준 첫 번째 값", "안쪽 쿼리가 돌려준 행의 개수"]', 1, '`EXISTS` 는 안쪽 쿼리에 행이 하나라도 있으면 참, 없으면 거짓입니다. 어떤 값을 고르는지는 상관없어서 관례로 `SELECT 1` 을 씁니다. 안쪽에서 바깥 테이블(`m.id`)을 참조하므로 회원마다 한 번씩 확인하는 셈입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 6, '큰 주문을 한 회원 (EXISTS)', '`mall` 데이터베이스(`mariadb -N mall -e ''쿼리''`)를 씁니다. `members`(id, name), `orders`(id, member_id, amount), `coupon_used`(member_id). `EXISTS` 로 **80000 이상인 주문을 한 적 있는 회원**의 이름을 `/tmp/whale.txt` 에 저장하세요. 바깥은 `members m`, 안쪽은 `orders o` 로 두고 `o.member_id = m.id` 로 회원과 연결합니다. (제목 줄 없이)', '`WHERE EXISTS (SELECT 1 FROM orders o WHERE o.member_id = m.id AND ...)` 모양입니다. 금액 조건은 안쪽 `WHERE` 에 `AND` 로 더하세요.', 'mariadb -N mall -e ''SELECT m.name FROM members m WHERE EXISTS (SELECT 1 FROM orders o WHERE o.member_id = m.id AND o.amount >= 80000)'' > /tmp/whale.txt
cat /tmp/whale.txt

# 회원마다 안쪽 쿼리에 행이 있는지 확인. 80000 이상 주문(90000)이 있는 park 만 남는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS mall; CREATE DATABASE mall; USE mall; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE orders (id INT PRIMARY KEY, member_id INT, amount INT); CREATE TABLE coupon_used (member_id INT); INSERT INTO members VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"),(4,\\"choi\\"),(5,\\"han\\"); INSERT INTO orders VALUES (1,1,30000),(2,1,70000),(3,2,15000),(4,3,50000),(5,3,20000),(6,3,90000); INSERT INTO coupon_used VALUES (1),(3),(NULL);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/whale.txt)\\" = 1 ] ) && ( [ \\"$(cat /tmp/whale.txt)\\" = park ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "한 줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/whale.txt)\\" = 1 ]"]}, {"label": "park 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/whale.txt)\\" = park ]"]}]', '[{"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB EXISTS", "url": "https://mariadb.com/kb/en/subqueries-and-exists/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 7, '주문이 하나도 없는 회원 (NOT EXISTS)', '`mall` 데이터베이스(`mariadb -N mall -e ''쿼리''`)를 씁니다. `members`(id, name), `orders`(id, member_id, amount), `coupon_used`(member_id). 반대로 **주문이 한 건도 없는 회원**의 이름을 `/tmp/idle.txt` 에 저장하세요. `EXISTS` 앞에 `NOT` 을 붙이면 "안쪽 쿼리에 행이 하나도 없다" 가 됩니다. (제목 줄 없이)', '`WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.member_id = m.id)` 모양입니다.', 'mariadb -N mall -e ''SELECT m.name FROM members m WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.member_id = m.id)'' > /tmp/idle.txt
cat /tmp/idle.txt

# 회원별로 주문이 없으면 NOT EXISTS 가 참. 앞에서 배운 LEFT JOIN ... IS NULL 과 같은 결과를 낸다 (choi, han)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS mall; CREATE DATABASE mall; USE mall; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE orders (id INT PRIMARY KEY, member_id INT, amount INT); CREATE TABLE coupon_used (member_id INT); INSERT INTO members VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"),(4,\\"choi\\"),(5,\\"han\\"); INSERT INTO orders VALUES (1,1,30000),(2,1,70000),(3,2,15000),(4,3,50000),(5,3,20000),(6,3,90000); INSERT INTO coupon_used VALUES (1),(3),(NULL);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/idle.txt)\\" = 2 ] ) && ( [ \\"$(sort /tmp/idle.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"choi han \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/idle.txt)\\" = 2 ]"]}, {"label": "choi·han 이다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/idle.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"choi han \\" ]"]}]', '[{"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB EXISTS", "url": "https://mariadb.com/kb/en/subqueries-and-exists/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 8, '주문이 없는 회원', '주문이 하나도 없는 회원을 찾는 쿼리입니다. 빈칸을 채우세요.', '"안쪽 쿼리에 행이 없다" 를 뜻하는 키워드를 고르세요.', NULL, NULL, '[]', 'fill', '["NOT EXISTS", "EXISTS", "NOT ANY", "LIKE"]', NULL, '`NOT EXISTS` 는 안쪽 쿼리 결과가 비어 있을 때 참입니다. 그냥 `EXISTS` 는 주문이 있는 회원을 고르고, 나머지는 서브쿼리 앞에 이런 식으로 쓸 수 없습니다.', '[0]', 'SELECT m.name FROM members m WHERE {0} (SELECT 1 FROM orders o WHERE o.member_id = m.id);', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 9, 'NOT IN 의 함정', '쿠폰을 쓴 회원 번호가 들어 있는 `coupon_used` 에는 값 `1`, `3` 과 **`NULL` 한 행**이 있습니다. `SELECT name FROM members WHERE id NOT IN (SELECT member_id FROM coupon_used)` 를 실행하면 어떻게 될까요?', '`NULL` 과의 비교 결과는 참도 거짓도 아닌 "알 수 없음" 입니다. 이 쿼리는 회원 번호가 `1`, `3`, `NULL` 이 **모두 아니어야** 합니다.', NULL, NULL, '[]', 'choice', '["쿠폰을 쓰지 않은 lee, choi, han 이 나온다", "한 행도 나오지 않는다", "NULL 행만 무시되어 lee, choi, han 이 나온다", "오류가 난다"]', 1, '`id NOT IN (1, 3, NULL)` 은 `id<>1 AND id<>3 AND id<>NULL` 과 같고, `id<>NULL` 은 항상 "알 수 없음" 이라 전체가 참이 될 수 없습니다. 목록에 `NULL` 이 하나라도 있으면 `NOT IN` 은 아무 행도 돌려주지 않습니다. 오류도 없이 조용히 빈 결과가 나와서 더 위험합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 10, 'NULL 이 섞여도 안전하게 거르기', '`mall` 데이터베이스(`mariadb -N mall -e ''쿼리''`)를 씁니다. `members`(id, name), `orders`(id, member_id, amount), `coupon_used`(member_id). 앞 문제의 쿼리는 `coupon_used` 에 `NULL` 이 있어서 결과가 비었습니다. **쿠폰을 쓰지 않은 회원**의 이름(lee, choi, han)이 나오도록 쿼리를 고쳐 `/tmp/nocoupon.txt` 에 저장하세요. `NOT EXISTS` 를 쓰거나, 서브쿼리에서 `NULL` 을 걸러내는 방법 중 편한 쪽을 쓰세요. (제목 줄 없이)', '`NOT EXISTS` 는 `NULL` 에 영향받지 않습니다. `NOT IN` 을 쓴다면 서브쿼리의 `WHERE` 에 `IS NOT NULL` 조건을 더합니다.', 'mariadb -N mall -e ''SELECT m.name FROM members m WHERE NOT EXISTS (SELECT 1 FROM coupon_used c WHERE c.member_id = m.id)'' > /tmp/nocoupon.txt
cat /tmp/nocoupon.txt

# NOT EXISTS 는 행이 있는지만 보므로 NULL 행이 있어도 안전하다. NOT IN 을 쓰려면 서브쿼리에 WHERE member_id IS NOT NULL', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS mall; CREATE DATABASE mall; USE mall; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE orders (id INT PRIMARY KEY, member_id INT, amount INT); CREATE TABLE coupon_used (member_id INT); INSERT INTO members VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"),(4,\\"choi\\"),(5,\\"han\\"); INSERT INTO orders VALUES (1,1,30000),(2,1,70000),(3,2,15000),(4,3,50000),(5,3,20000),(6,3,90000); INSERT INTO coupon_used VALUES (1),(3),(NULL);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/nocoupon.txt)\\" = 3 ] ) && ( [ \\"$(sort /tmp/nocoupon.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"choi han lee \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/nocoupon.txt)\\" = 3 ]"]}, {"label": "lee·choi·han 이다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/nocoupon.txt | tr \\"\\\\n\\" \\" \\")\\" = \\"choi han lee \\" ]"]}]', '[{"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB EXISTS", "url": "https://mariadb.com/kb/en/subqueries-and-exists/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 11, '합계의 평균 구하기 (FROM 절 서브쿼리)', '`mall` 데이터베이스(`mariadb -N mall -e ''쿼리''`)를 씁니다. `members`(id, name), `orders`(id, member_id, amount), `coupon_used`(member_id). **회원별 주문 합계**를 먼저 구하고, 그 합계들의 **평균**을 구하려 합니다. `AVG(SUM(...))` 처럼 집계 함수를 겹쳐 쓸 수는 없지만, **`FROM` 절에 서브쿼리를 넣어 임시 표(파생 테이블)로 만들면** 가능합니다. 파생 테이블에는 반드시 별칭이 필요합니다. 주문한 회원들의 합계 평균을 `/tmp/avg_total.txt` 에 저장하세요. (제목 줄 없이 숫자 하나)', '안쪽 `SELECT member_id, SUM(amount) AS total FROM orders GROUP BY member_id` 를 `FROM ( ... ) t` 처럼 괄호와 별칭으로 감싸고, 바깥에서 `AVG(total)` 을 구합니다.', 'mariadb -N mall -e ''SELECT AVG(total) FROM (SELECT member_id, SUM(amount) AS total FROM orders GROUP BY member_id) t'' > /tmp/avg_total.txt
cat /tmp/avg_total.txt

# 안쪽이 회원별 합계 표(100000, 15000, 160000)를 만들고, 바깥이 그 표의 평균(약 91666.67)을 구한다. FROM 의 서브쿼리는 별칭 필수', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS mall; CREATE DATABASE mall; USE mall; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE orders (id INT PRIMARY KEY, member_id INT, amount INT); CREATE TABLE coupon_used (member_id INT); INSERT INTO members VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"),(4,\\"choi\\"),(5,\\"han\\"); INSERT INTO orders VALUES (1,1,30000),(2,1,70000),(3,2,15000),(4,3,50000),(5,3,20000),(6,3,90000); INSERT INTO coupon_used VALUES (1),(3),(NULL);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/avg_total.txt ] ) && ( grep -q \\"^91666\\" /tmp/avg_total.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/avg_total.txt ]"]}, {"label": "평균 91666 대이다", "cmd": ["sh", "-c", "grep -q \\"^91666\\" /tmp/avg_total.txt"]}]', '[{"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB EXISTS", "url": "https://mariadb.com/kb/en/subqueries-and-exists/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 522, 12, '회원 등급 나누기 (파생 테이블 + CASE)', '`mall` 데이터베이스(`mariadb -N mall -e ''쿼리''`)를 씁니다. `members`(id, name), `orders`(id, member_id, amount), `coupon_used`(member_id). 모든 회원의 이름과 등급을 `/tmp/grade.txt` 에 저장하세요. 등급(`CASE`): 주문 합계 **100000 이상이면 `vip`**, 주문이 있으면 `normal`, 주문이 없으면 `none`. `members` 와 **회원별 합계 파생 테이블 `t`** 를 `LEFT JOIN` 해서(주문 없는 회원도 남도록), 합계가 `NULL` 인 것을 "주문 없음" 으로 보세요. 열은 이름, 등급 순입니다. (제목 줄 없이)', '`FROM members m LEFT JOIN (SELECT member_id, SUM(amount) AS total FROM orders GROUP BY member_id) t ON t.member_id = m.id` 로 잇고, `CASE WHEN t.total >= ... THEN ... WHEN t.total IS NOT NULL THEN ... ELSE ... END` 로 분류합니다.', 'mariadb -N mall -e "SELECT m.name, CASE WHEN t.total >= 100000 THEN ''vip'' WHEN t.total IS NOT NULL THEN ''normal'' ELSE ''none'' END FROM members m LEFT JOIN (SELECT member_id, SUM(amount) AS total FROM orders GROUP BY member_id) t ON t.member_id = m.id" > /tmp/grade.txt
cat /tmp/grade.txt

# 파생 테이블로 합계를 만들고 LEFT JOIN 으로 이은 뒤 CASE 가 위에서부터 차례로 검사한다 (kim vip, lee normal, park vip, choi none, han none)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS mall; CREATE DATABASE mall; USE mall; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE orders (id INT PRIMARY KEY, member_id INT, amount INT); CREATE TABLE coupon_used (member_id INT); INSERT INTO members VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"),(4,\\"choi\\"),(5,\\"han\\"); INSERT INTO orders VALUES (1,1,30000),(2,1,70000),(3,2,15000),(4,3,50000),(5,3,20000),(6,3,90000); INSERT INTO coupon_used VALUES (1),(3),(NULL);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/grade.txt)\\" = 5 ] ) && ( awk -F\\"\\\\t\\" ''$1==\\"kim\\"&&$2==\\"vip\\"{a=1} $1==\\"lee\\"&&$2==\\"normal\\"{b=1} $1==\\"han\\"&&$2==\\"none\\"{c=1} END{exit !(a&&b&&c)}'' /tmp/grade.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "5줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/grade.txt)\\" = 5 ]"]}, {"label": "kim 은 vip, lee 는 normal, han 은 none", "cmd": ["sh", "-c", "awk -F\\"\\\\t\\" ''$1==\\"kim\\"&&$2==\\"vip\\"{a=1} $1==\\"lee\\"&&$2==\\"normal\\"{b=1} $1==\\"han\\"&&$2==\\"none\\"{c=1} END{exit !(a&&b&&c)}'' /tmp/grade.txt"]}]', '[{"title": "MariaDB 서브쿼리", "url": "https://mariadb.com/kb/en/subqueries/"}, {"title": "MariaDB EXISTS", "url": "https://mariadb.com/kb/en/subqueries-and-exists/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 522 AND order_index = 12);
